import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default async function createNode(config, ctx) {
  const { Mesh, PlaneGeometry, Group } = ctx.THREE;

  const group = new Group();
  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Geometry: 512px / 320px ≈ 1.6:1 aspect
  const aspect = 512 / 320;
  const height = 2.0;
  const width = height * aspect;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  // Load the image
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  let imageTex = null;

  try {
    imageTex = await ctx.textureLoader.loadTexture(imageUrl);
    imageTex.colorSpace = 'srgb';
  } catch (err) {
    console.warn('Failed to load image texture:', err);
  }

  // TSL material with engineered grain overlay
  const uvNode = uv();

  // Grain pattern (subtle procedural noise simulation via sin/cos modulation)
  const grainAmount = 0.03;
  const grain = mix(
    vec3(1.0),
    vec3(
      Math.sin(uvNode.x * 50.0 + uvNode.y * 30.0) * 0.5 + 0.5,
      Math.cos(uvNode.x * 40.0 + uvNode.y * 40.0) * 0.5 + 0.5,
      Math.sin((uvNode.x + uvNode.y) * 35.0) * 0.5 + 0.5
    ),
    grainAmount
  );

  let colorNode = imageTex ? texture(imageTex, uvNode) : vec3(0.1, 0.1, 0.1);
  colorNode = mix(colorNode, grain, grainAmount);

  const material = new MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
    side: 2, // DoubleSide
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (imageTex) {
      imageTex.dispose();
    }
  };

  group.userData.handlers = {};

  return group;
}
